const NS='http://www.w3.org/2000/svg';
const STATUS_COLORS={available:'#23805b',reserved:'#bd8422',sold_out:'#a83c58'};
export class PlanView{
 constructor(el,onSelect,onHover,onPin,locale){Object.assign(this,{el,onSelect,onHover,onPin,locale,hall:1,selected:null,category:'all',directions:true});this.pointers=new Map();this.bookings=new Set();this.statuses=new Map();this.setHall(1);this.resizeObserver=new ResizeObserver(()=>this.projectPin());this.resizeObserver.observe(this.el);}
 setHall(h){this.stopTransition();this.pointers.clear();this.hall=h;const d=halls[h];this.base={x:-4,y:-4,w:d.width+8,h:d.depth+10};this.camera={...this.base};this.selected=null;this.render();}
 render(){const focused=this.el.querySelector(':focus')?.dataset.mapStall;const t=this.locale().t,h=halls[this.hall],nav=circulation[this.hall];
 const defs=`<defs><pattern id="masonry-bond" width="2.4" height="1.2" patternUnits="userSpaceOnUse"><rect width="2.4" height="1.2" fill="#b2b9aa"/><path d="M0 .6h2.4M1.2 0v.6M0 .6v.6M2.4 .6v.6" stroke="#edf0e7" stroke-width=".12"/></pattern><pattern id="plan-hatch" width="2" height="2" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="2" height="2" fill="#faf2df"/><path d="M0 0v2" stroke="#d9977d" stroke-width=".4"/></pattern><filter id="plan-shadow" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="1.1" stdDeviation="1.4" flood-color="#164631" flood-opacity=".17"/></filter><filter id="stall-glow" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow stdDeviation=".6" flood-color="#d9ae43" flood-opacity=".9"/></filter></defs>`;
 const outline=nav.outline.map(p=>p.join(',')).join(' ');
 const walls=nav.walls.map(([a,b])=>`<path class="perimeter-wall" d="M${a.join(' ')}L${b.join(' ')}"/>`).join('');
 const barriers=(nav.barriers||[]).map(b=>`<g class="plan-barrier" data-barrier="${b.id}"><title>${t('barrier')}</title><rect x="${b.x}" y="${b.z}" width="${b.w}" height="${b.d}" fill="url(#masonry-bond)" stroke="#245c55" stroke-width=".24"/></g>`).join('');
 const lanes=nav.lanes.map(l=>`<g class="plan-lane" data-lane="${l.id}"><path class="lane-guide" d="${l.points.map((p,i)=>(i?'L':'M')+p.join(' ')).join('')}"/>${l.points.slice(1).map((b,i)=>{const a=l.points[i],len=Math.hypot(b[0]-a[0],b[1]-a[1]),angle=Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI;return Array.from({length:Math.max(1,Math.floor(len/8))},(_,j)=>{const f=(j+.5)/Math.max(1,Math.floor(len/8));return`<g transform="translate(${a[0]+(b[0]-a[0])*f} ${a[1]+(b[1]-a[1])*f}) rotate(${angle})"><path class="flow-chevron" d="m-.8-.65.8.65-.8.65M-.9 0H.3" style="animation-delay:${-(j%4)*.32}s"/></g>`;}).join('');}).join('')}</g>`).join('');
 const facilities=h.facilities.map(f=>{const cx=f.x+f.w/2,cz=f.z+f.d/2,vertical=f.d>f.w*1.8,fill=f.type==='zone'?'#c1dfce':f.type==='passage'?'#e5eddd':f.type==='stairs'?'#c5cfbf':'url(#plan-hatch)';const steps=f.type==='stairs'?Array.from({length:7},(_,i)=>`<path d="M${f.x+.4} ${f.z+(i+.5)*f.d/7}h${f.w-.8}" stroke="#667d65" stroke-width=".25"/>`).join(''):'';return`<g class="plan-facility"><rect x="${f.x}" y="${f.z}" width="${f.w}" height="${f.d}" fill="${fill}" stroke="#8ca383" stroke-width=".25" rx=".4"/>${steps}<g transform="translate(${cx} ${cz})${vertical?' rotate(-90)':''}">${f.n?`<text y="-.5" class="facility-number">${f.n}</text>`:''}<text y="${f.n?2.5:0}" class="facility-label">${t(f.key)}</text></g></g>`;}).join('');
 const booths=stalls.filter(s=>s.hall===this.hall).map(s=>`<g class="map-stall" role="button" tabindex="${s.n===(this.selected??(this.hall===1?1:120))?0:-1}" data-map-stall="${s.n}" aria-label="${t('stall')} ${s.n}, ${t(s.tier)}"><title>${t('stall')} ${s.n} · ${t(s.tier)}</title><rect class="stall-tile" x="${s.x+.12}" y="${s.z+.12}" width="${s.w-.24}" height="${s.d-.24}" rx=".35" fill="${colors[s.color]}"/><g class="map-booking-marker" aria-hidden="true"><circle cx="${s.x+s.w-.65}" cy="${s.z+.65}" r=".5" fill="#983f51"/><text x="${s.x+s.w-.65}" y="${s.z+.65}" fill="#fff" font-family="Arial,sans-serif" font-size=".75" font-weight="800">S</text></g><text class="stall-number" style="font-size:${Math.min(2.75,(s.w-.65)/(String(s.n).length*.62))}px" x="${s.x+s.w/2}" y="${s.z+s.d/2}">${s.n}${s.n===149?'*':''}</text></g>`).join('');
 const portals=nav.portals.map(p=>`<g class="plan-portal"><path d="${p.side==='east'?`M114 ${p.from}V${p.to}`:`M${p.from} ${p.side==='south'?110:0}H${p.to}`}" stroke="#92bb56" stroke-width="1.5"/><text class="portal-label" x="${p.side==='east'?p.x-2:p.x}" y="${p.side==='south'?p.z+5:p.side==='north'?-1.8:p.z-2}" text-anchor="${p.side==='east'?'end':'middle'}">${t(p.key)} ${p.side==='east'?'←':'↑'}</text></g>`).join('');
 this.el.innerHTML=`<svg xmlns="${NS}" class="interactive-plan" viewBox="${this.camera.x} ${this.camera.y} ${this.camera.w} ${this.camera.h}" role="group" aria-label="${t('hall')} ${this.hall}">${defs}<polygon points="${outline}" fill="#faf9f0" filter="url(#plan-shadow)"/><g class="plan-directions">${lanes}</g>${facilities}${booths}<g class="plan-barriers">${barriers}</g>${this.hall===1?'<g class="brand-visibility" stroke="#67408d" stroke-width=".6"><path d="M23 16.1h16M52 16.1h16M83 1h22"/></g>':''}<g class="plan-perimeter">${walls}</g>${portals}<g id="plan-selection-overlay" pointer-events="none"></g></svg>`;this.svg=this.el.querySelector('svg');this.update();this.bind();if(focused)this.el.querySelector(`[data-map-stall="${focused}"]`)?.focus({preventScroll:true});}
 update({selected=this.selected,category=this.category,directions=this.directions}={}){if(selected==null&&this.selected!=null)this.stopTransition();this.selected=selected;this.category=category;this.directions=directions;this.el.querySelector('.plan-directions')?.classList.toggle('off',!directions);for(const el of this.el.querySelectorAll('[data-map-stall]')){const n=Number(el.dataset.mapStall),s=stalls[n-1],active=n===selected;el.classList.toggle('selected',active);const status=this.bookingStatus(n),booked=status==='reserved'||status==='sold_out',statusText=status?this.locale().t({available:'bookingAvailable',reserved:'bookingReserved',sold_out:'bookingSoldOut'}[status]):'';el.classList.toggle('is-booked',booked);for(const key of['available','reserved','sold_out'])el.classList.toggle('is-'+key.replace('_','-'),status===key);el.setAttribute('aria-label',`${this.locale().t('stall')} ${n}, ${this.locale().t(s.tier)}${statusText?', '+statusText:''}`);const marker=el.querySelector?.('.map-booking-marker');if(marker){marker.style.display=booked?'block':'none';const circle=marker.querySelector('circle'),symbol=marker.querySelector('text');circle?.setAttribute('fill',STATUS_COLORS[status]||STATUS_COLORS.sold_out);if(symbol)symbol.textContent=status==='reserved'?'R':status==='sold_out'?'S':'✓';}el.querySelector?.('title')?.replaceChildren(`${this.locale().t('stall')} ${n} · ${this.locale().t(s.tier)}${statusText?' · '+statusText:''}`);el.classList.toggle('dimmed',category!=='all'&&s.tier!==category&&!active);el.setAttribute('aria-pressed',String(active));el.tabIndex=n===(selected??(this.hall===1?1:120))?0:-1;}
 const s=stalls.find(s=>s.n===selected);const overlay=this.el.querySelector('#plan-selection-overlay');if(overlay)overlay.innerHTML=s?`<rect class="selection-outline" x="${s.x-.12}" y="${s.z-.12}" width="${s.w+.24}" height="${s.d+.24}" rx=".6"/><circle class="selection-access" cx="${accessPoint(s).x}" cy="${accessPoint(s).z}" r=".8"/>`:'';this.projectPin();}
 bookingStatus(n){const status=this.statuses?.get(n);return ['available','reserved','sold_out'].includes(status)?status:this.bookings?.has(n)?'sold_out':null;}
 setBookings(values,statuses=new Map()){this.bookings=new Set(values);this.statuses=new Map(statuses);this.update();}
 screenPoint(clientX,clientY){const p=this.svg.createSVGPoint();p.x=clientX;p.y=clientY;return p.matrixTransform(this.svg.getScreenCTM().inverse());}
 bind(){const svg=this.svg;let start=null,dragged=false;svg.addEventListener('pointerdown',e=>{this.stopTransition();this.pointers.set(e.pointerId,[e.clientX,e.clientY]);start={x:e.clientX,y:e.clientY,camera:{...this.camera},point:this.screenPoint(e.clientX,e.clientY),inverse:svg.getScreenCTM().inverse(),target:e.target.closest('[data-map-stall]')?.dataset.mapStall};dragged=false;svg.setPointerCapture(e.pointerId);if(this.pointers.size===2)this.pinchDistance=this.pinch();});
 svg.addEventListener('pointermove',e=>{if(this.pointers.has(e.pointerId)){this.pointers.set(e.pointerId,[e.clientX,e.clientY]);if(this.pointers.size===2){const next=this.pinch();if(this.pinchDistance)this.zoom(next/this.pinchDistance);this.pinchDistance=next;dragged=true;return;}if(start){const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>4){dragged=true;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const world=point.matrixTransform(start.inverse);this.camera.x=start.camera.x-(world.x-start.point.x);this.camera.y=start.camera.y-(world.y-start.point.y);this.applyCamera();this.onHover(null);}}}else{const el=e.target.closest('[data-map-stall]');svg.querySelector('.hovered')?.classList.remove('hovered');if(el){el.classList.add('hovered');this.onHover({n:Number(el.dataset.mapStall),clientX:e.clientX,clientY:e.clientY});}else this.onHover(null);}});
 svg.addEventListener('pointerup',e=>{this.pointers.delete(e.pointerId);if(!dragged&&this.pointers.size===0&&start?.target)this.onSelect(Number(start.target));start=null;});svg.addEventListener('pointercancel',e=>{this.pointers.delete(e.pointerId);start=null;});svg.addEventListener('pointerleave',()=>{svg.querySelector('.hovered')?.classList.remove('hovered');this.onHover(null);});svg.addEventListener('wheel',e=>{e.preventDefault();this.zoom(Math.exp(-e.deltaY*.0015),this.screenPoint(e.clientX,e.clientY));},{passive:false});svg.addEventListener('keydown',e=>{const el=e.target.closest('[data-map-stall]');if(!el)return;const n=Number(el.dataset.mapStall);if(e.key==='Enter'||e.key===' '){e.preventDefault();this.onSelect(n);return;}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const a=stalls[n-1],dx=e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0,dz=e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0;const candidates=stalls.filter(s=>s.hall===this.hall&&s.n!==n).map(s=>{const x=s.x+s.w/2-a.x-a.w/2,z=s.z+s.d/2-a.z-a.d/2,along=x*dx+z*dz,across=Math.abs(x*dz-z*dx);return{s,along,score:along+across*2.5};}).filter(v=>v.along>.4).sort((a,b)=>a.score-b.score);if(candidates[0]){const next=candidates[0].s.n;this.onSelect(next);this.el.querySelector(`[data-map-stall="${next}"]`)?.focus({preventScroll:true});}});}
 pinch(){const p=[...this.pointers.values()];return p.length===2?Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]):0;}
 applyCamera(){this.svg?.setAttribute('viewBox',`${this.camera.x} ${this.camera.y} ${this.camera.w} ${this.camera.h}`);this.projectPin();}
 zoom(factor,point){this.stopTransition();const old=this.camera,w=Math.max(this.base.w/5,Math.min(this.base.w*1.05,old.w/factor)),ratio=w/old.w,h=old.h*ratio,cx=point?.x??old.x+old.w/2,cy=point?.y??old.y+old.h/2;this.camera={x:cx-(cx-old.x)*ratio,y:cy-(cy-old.y)*ratio,w,h};this.applyCamera();}
 stopTransition(){if(this.transitionFrame)cancelAnimationFrame(this.transitionFrame);this.transitionFrame=null;this.svg?.removeAttribute('data-focusing');}
 focus(n,{immediate=false}={}){const s=stalls[n-1];if(!s||s.hall!==this.hall)return;this.stopTransition();const target=planFocus(s,this.base),start={...this.camera};if(immediate||matchMedia('(prefers-reduced-motion: reduce)').matches){this.camera=target;this.applyCamera();return;}const began=performance.now();this.svg?.setAttribute('data-focusing','true');const frame=now=>{const progress=Math.min(1,(now-began)/560),ease=1-Math.pow(1-progress,3);for(const key of['x','y','w','h'])this.camera[key]=start[key]+(target[key]-start[key])*ease;this.applyCamera();if(progress<1)this.transitionFrame=requestAnimationFrame(frame);else{this.transitionFrame=null;this.svg?.removeAttribute('data-focusing');}};this.transitionFrame=requestAnimationFrame(frame);}
 reset(){this.stopTransition();this.camera={...this.base};this.applyCamera();}
 projectPin(){if(!this.svg||!this.selected){this.onPin?.(null);return;}const s=stalls[this.selected-1],p=this.svg.createSVGPoint();p.x=s.x+s.w/2;p.y=s.z-.8;const matrix=this.svg.getScreenCTM();if(!matrix)return;const xy=p.matrixTransform(matrix),r=this.el.parentElement.getBoundingClientRect(),tile=this.el.querySelector(`[data-map-stall="${s.n}"] .stall-tile`)?.getBoundingClientRect();this.onPin?.({x:xy.x-r.left,y:xy.y-r.top,bounds:tile?{top:tile.top-r.top,bottom:tile.bottom-r.top}:null,visible:xy.x>=r.left&&xy.x<=r.right&&xy.y>=r.top&&xy.y<=r.bottom});}
 localize(){this.render();}
}
